// Tres portas de entrada convergem aqui:
// - Telegram (Fase 4): chega a URL assinada do PDF recem-guardado; o resto vem
//   do 'Triar mensagem'.
// - Execute Sub-workflow (testes): { empresa_id, obra_id, arquivo_url, canal,
//   chat_id, numero_contrato? }.
// obra_id pode faltar (contato sem obra): nao e erro aqui, vira REVISAO_HUMANA
// em 'Analisar e decidir'. A proposta se liga a OBRA (decisao 16).
let e = $input.first().json ?? {};
// - Webhook (Fase 7): envio pela tela /documentos. O corpo vem em .body; o
//   documento ja foi gravado pela action (documento_id) e e reaproveitado.
if (e.body && e.headers) e = e.body;
if (e.signedURL) {
  const t = $('Triar mensagem').first().json;
  e = {
    empresa_id: t.empresa_id,
    obra_id: t.obra_id,
    arquivo_url: 'https://gzbmhgnpoehormnidmgg.supabase.co/storage/v1' + e.signedURL,
    canal: 'TELEGRAM',
    chat_id: t.chat_id,
    remetente_id: t.remetente_id ?? null,
    mensagem_id: t.mensagem_id ?? null,
  };
}
const pelaTela = String(e.canal || '').toUpperCase() === 'SISTEMA';
// Pela tela nao ha conversa: o aviso ao 'cliente' e pulado (Preparar envio
// ignora destino sem chat_id); so o grupo de admin recebe.
const faltando = ['empresa_id', 'arquivo_url'].concat(pelaTela ? [] : ['chat_id']).filter((k) => !e[k]);
if (faltando.length) throw new Error('Entrada incompleta: faltam ' + faltando.join(', '));
return [{
  json: {
    empresa_id: e.empresa_id,
    obra_id: e.obra_id || null,
    arquivo_url: e.arquivo_url,
    canal: String(e.canal || 'TELEGRAM').toUpperCase(),
    chat_id: pelaTela ? null : String(e.chat_id),
    remetente_id: e.remetente_id ?? null,
    mensagem_id: e.mensagem_id ?? null,
    documento_id: e.documento_id || null,
    nome_arquivo: e.nome_arquivo || null,
    numero_contrato: e.numero_contrato || null,
    // Canal so de propostas (decisao 18): e o tipo provisorio ate o Gemini classificar.
    tipo_documento: e.tipo_documento === 'CONTRATO' ? 'CONTRATO' : 'PROPOSTA',
  },
}];

// Junta o antigo 'Parsear Resposta da IA' e a antiga Triagem num lugar so.
// Proposta e contrato entram (decisao 23, que revoga a 18); a gravacao e das
// rotas do gc-sistema (decisao 26).
// A proposta se liga a OBRA (decisao 16), que vem do contato.
const ent = $('Normalizar entrada').first().json;
const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let dados;
try { dados = JSON.parse(raw); } catch (err) { dados = {}; }

// Fase 5: itens extraidos LITERAIS (numero e unidade como escritos). A traducao
// para as colunas de itens e da Fase 6, com os helpers de src/lib/itens.ts
// (numeroItemDoDocumento, normalizarUnidade, resolverValorUnit). Aqui so se
// garante que numero em texto brasileiro vire number.
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return Number.isFinite(v) ? v : null;
  const s = String(v).replace(/R\$/gi, '').replace(/\s/g, '');
  const t = /,\d{1,2}$/.test(s) ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  const n = Number(t);
  return Number.isFinite(n) ? n : null;
};
const texto = (v) => (v === null || v === undefined || String(v).trim() === '' ? null : String(v).trim());
const itens = (Array.isArray(dados.itens) ? dados.itens : []).map((it) => ({
  numero: texto(it?.numero),
  tipo: texto(it?.tipo),
  linha: texto(it?.linha),
  acabamento: texto(it?.acabamento),
  localizacao: texto(it?.localizacao),
  descricao: texto(it?.descricao),
  quantidade: num(it?.quantidade),
  unidade: texto(it?.unidade),
  valor_unitario: num(it?.valor_unitario),
  valor_total: num(it?.valor_total),
  largura: num(it?.largura),
  altura: num(it?.altura),
  vidros: texto(it?.vidros),
  observacao: texto(it?.observacao),
}));
// Diagnostico, NAO bloqueia: os itens so sao gravados na Fase 6.
// Decisao 10: item sem unitario tem o valor inferido de total/quantidade na
// gravacao; item sem nenhum dos dois, ou sem quantidade, nao tem conserto.
const itensSemUnitario = itens.filter((it) => it.valor_unitario === null && it.valor_total !== null).map((it) => it.numero);
const itensSemConserto = itens.filter((it) => (it.valor_unitario === null && it.valor_total === null) || !it.quantidade).map((it) => it.numero);
const somaItens = itens.reduce((acc, it) => acc + (it.valor_total ?? (it.quantidade ?? 0) * (it.valor_unitario ?? 0)), 0);
const valorProposta = num(dados.valor_total) || 0;
// Itens confiaveis? Numero de item repetido e o sinal de texto embaralhado:
// o extrator de texto do n8n (usado pela reserva Groq) mistura as colunas de
// PDF em duas colunas e o valor de um item cai no do vizinho (visto no
// EB-25-08-0048, itens 6/7 e 8/9). Cabecalho segue confiavel; os itens nao.
const contagemNumeros = {};
for (const it of itens) if (it.numero) contagemNumeros[it.numero] = (contagemNumeros[it.numero] || 0) + 1;
const numerosRepetidos = Object.keys(contagemNumeros).filter((k) => contagemNumeros[k] > 1);
const divergeSoma = itens.length > 0 && valorProposta > 0 && Math.abs(somaItens - valorProposta) > 0.01 * valorProposta;
const tipoDocumento = String(dados.tipo_documento || '').toUpperCase() === 'PROPOSTA' ? 'PROPOSTA' : 'CONTRATO';

const camposFaltando = [];
if (!dados.cliente_nome) camposFaltando.push('nome do cliente');
if (!dados.valor_total) camposFaltando.push('valor total');
if (!dados.condicoes_pagamento) camposFaltando.push('condições de pagamento');
if (!dados.condicao_entrega) camposFaltando.push('condição de entrega');

// Proposta: so o valor bloqueia; o resto se completa depois (reuniao de 12/08/2026).
const precisaComplementar = camposFaltando.length > 0;
// Decisao 27: a obra sai do documento; a rota identifica pelas pistas. obraId
// so vem quando alguem escolheu na tela (envio ou reprocesso).
const obraId = ent.obra_id || null;
const obraCodigo = dados.obra_codigo ? String(dados.obra_codigo).trim() : null;
const obraNome = dados.obra_nome ? String(dados.obra_nome).trim() : null;
const numero = dados.numero_contrato || ent.numero_contrato || null;

// Decisão 23 (revoga a 18): contrato também entra. Mesma régua da proposta:
// só o valor bloqueia; obra e número faltando vão para revisão.
const rotulo = tipoDocumento === 'PROPOSTA' ? 'a proposta' : 'o contrato';
let desfecho = tipoDocumento;
let motivo = null;
if (!dados.valor_total) {
  desfecho = 'ERRO_VALIDACAO';
  motivo = 'Não conseguimos identificar o valor total no seu documento. Pode reenviar o documento completo ou nos passar o valor por aqui?';
} else if (!numero) {
  desfecho = 'REVISAO_HUMANA';
  motivo = 'não encontramos o número d' + (tipoDocumento === 'PROPOSTA' ? 'a proposta' : 'o contrato') + ' no documento. Pode nos informar?';
}

return [{
  json: {
    ...dados,
    itens,
    tipoDocumento,
    valorProposta,
    somaItens,
    divergeSoma,
    itensSemUnitario,
    itensSemConserto,
    camposFaltando,
    precisaComplementar,
    obraId,
    obraCodigo,
    obraNome,
    numero,
    // Opção 1.a: número do contrato de que a proposta é aditivo.
    contratoAditivo: tipoDocumento === 'PROPOSTA' && dados.contrato_aditivo ? String(dados.contrato_aditivo).trim() : null,
    numerosRepetidos,
    itensConfiaveis: numerosRepetidos.length === 0 && !divergeSoma,
    // Qual IA extraiu (decisao 20): gemini, ou groq quando o Gemini falhou.
    extrator: $json.extrator || 'gemini',
    motivoGemini: $json.motivoGemini || null,
    desfecho,
    status: desfecho === 'PROPOSTA' || desfecho === 'CONTRATO' ? 'APROVADO' : desfecho,
    motivo,
  },
}];

// Recebe a saida de erro de qualquer etapa depois que o registro existe.
// Documento com falha vai para REVISAO_HUMANA com motivo legivel, para nao
// ficar preso em PENDENTE sem ninguem ver.
const etapa = $input.first().json.etapa || $prevNode.name;
const j = $input.first().json ?? {};
const erro = [j.error?.message, j.error?.description].filter(Boolean).join(' — ') || (typeof j.error === 'string' ? j.error : JSON.stringify(j).slice(0, 300));
let A = {};
try { A = $('Analisar e decidir').first().json; } catch (e) { A = {}; }
let motivoGemini = null;
try { motivoGemini = $('Reserva - PDF de volta').first().json.motivoGemini; } catch (e) { motivoGemini = null; }

// Erros das rotas do gc-sistema: o n8n poe "409 - {corpo}" na mensagem.
const naRota = etapa === 'Rota - Gravar no sistema';
const statusRota = naRota ? Number((String(j.error?.message || '').match(/^(\d{3})/) || [])[1] || 0) : 0;
let erroRota = null;
// Decisão 31: obra não identificada vem com a pergunta pronta para o bot.
let perguntaRota = null;
if (naRota) {
  // O n8n poe o corpo como texto JSON, as vezes com as aspas escapadas
  // (409 - "{\"ok\":false,\"error\":\"...\"}"). Le o objeto e pega .error.
  const msg = String(j.error?.message || '') + ' ' + String(j.error?.description || '');
  const ini = msg.indexOf('{');
  const fim = msg.lastIndexOf('}');
  if (ini >= 0 && fim > ini) {
    const trecho = msg.slice(ini, fim + 1);
    for (const tentativa of [trecho, trecho.replace(/\\"/g, '"')]) {
      try { const o = JSON.parse(tentativa); if (o && typeof o.error === 'string') { erroRota = o.error; perguntaRota = typeof o.pergunta === 'string' ? o.pergunta.replace(/\\n/g, '\n') : null; break; } } catch (e) {}
    }
  }
  if (!erroRota) erroRota = erro;
}
const tipo = A.desfecho === 'CONTRATO' ? 'contrato' : 'proposta';
let motivo;
let falha = true;
if (naRota && statusRota === 409 && /obra já tem um contrato/i.test(erroRota || '')) {
  // Regra do Breno (25/09): obra tem UM contrato vigente. Pode ser aditivo ou reenvio.
  falha = false;
  motivo = (erroRota || 'a obra já tem um contrato vigente').replace(/^A obra/, 'a obra') + '. Nossa equipe vai verificar se é um aditivo ou um reenvio.';
} else if (naRota && statusRota === 409) {
  // Numero repetido e resultado esperado (decisao 9), nao erro.
  falha = false;
  motivo = 'já existe ' + (tipo === 'contrato' ? 'um contrato' : 'uma proposta') + ' com o número ' + (A.numero || '(sem número)') + ' registrad' + (tipo === 'contrato' ? 'o' : 'a') + '. Nossa equipe vai revisar.';
} else if (naRota && statusRota === 422) {
  // Recusado pela regra (item sem conserto, obra de outra empresa): revisao.
  falha = false;
  motivo = 'não foi possível registrar automaticamente (' + erroRota + '). Nossa equipe vai revisar.';
} else if (naRota && statusRota === 404) {
  // Rota de contrato ainda nao publicada na Vercel (precisa do merge).
  falha = false;
  motivo = 'recebemos o documento e nossa equipe vai registrá-lo. (A entrada automática de ' + tipo + 's ainda não está publicada no sistema.)';
} else {
  motivo = 'falha técnica na etapa "' + etapa + '": ' + (erroRota || erro) + (motivoGemini && etapa !== 'Gemini - Extrair dados' ? ' (antes, o Gemini: ' + motivoGemini + ')' : '');
}
return [{ json: { ...A, status: 'REVISAO_HUMANA', falha, etapa, erro: erroRota || erro, motivo, pergunta: naRota && statusRota === 422 ? perguntaRota : null } }];

// Um lugar so para todos os textos: cliente e grupo de admin. Sai em 2 itens,
// e o Notificar envia os dois.
// Referencias LITERAIS de proposito: o executor de codigo do n8n 2.x so envia ao
// Code node os dados dos nos citados pelo nome no texto. $(variavel) chega vazio.
const ent = $('Normalizar entrada').first().json;
let A = {};
try { A = $('Analisar e decidir').first().json; } catch (e) { A = {}; }
let F = null;
try { F = $('Registrar falha').first().json; } catch (e) { F = null; }
// first(0): o 'Criar registro' tem a saida de ERRO ligada direto aqui, e sem o
// indice o n8n le esse ramo (vazio). A saida 0 e a do registro criado.
let reg = null;
try { reg = $('Supabase - Criar registro').first(0).json; } catch (e) { reg = null; }
const docId = reg?.id ?? null;
const etapaAnterior = $prevNode.name;
const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2);
const num = A.numero ? ' nº ' + A.numero : '';

let cliente;
let admin;
if (etapaAnterior === 'Supabase - Criar registro') {
  const erro = $json.error?.message || JSON.stringify($json).slice(0, 300);
  cliente = 'Tivemos um problema ao receber seu documento. Nossa equipe já foi avisada e vai te retornar em breve.';
  admin = '[ERRO] Não foi possível registrar o documento recebido.\nErro: ' + erro;
} else if (F && F.falha) {
  cliente = 'Tivemos um problema processando seu documento. Nossa equipe já foi avisada e vai te retornar em breve.';
  admin = '[ERRO] Documento ' + docId + '\nEtapa: ' + F.etapa + '\nErro: ' + F.erro;
} else if (F && F.pergunta && ent.chat_id) {
  // Decisão 31: em vez de só revisão, pergunta a obra a quem enviou.
  cliente = 'Recebemos seu documento, mas não encontramos a obra dele no sistema.\n\n' + F.pergunta + (String(ent.chat_id).startsWith('-') ? '\n\nResponda a esta mensagem com o número da obra.' : '');
  admin = '[PERGUNTA DE OBRA] Documento ' + docId + ' · ' + (A.desfecho === 'CONTRATO' ? 'contrato' : 'proposta') + num + '\n' + F.motivo + '\nPerguntamos a obra a quem enviou; se a resposta for "nenhuma", fica para revisão.';
} else if (F) {
  cliente = 'Recebemos seu documento, mas ' + F.motivo;
  admin = '[REVISÃO] Documento ' + docId + ' · ' + (A.desfecho === 'CONTRATO' ? 'contrato' : 'proposta') + num + '\n' + F.motivo;
} else if (A.desfecho === 'ERRO_VALIDACAO') {
  cliente = A.motivo;
  admin = '[ERRO DE VALIDAÇÃO] Documento ' + docId + ' · sem valor total';
} else if (A.desfecho === 'REVISAO_HUMANA') {
  cliente = 'Recebemos seu documento, mas ' + A.motivo;
  admin = '[REVISÃO] Documento ' + docId + ' · ' + (A.tipoDocumento === 'PROPOSTA' ? 'proposta' : 'contrato') + num + '\n' + A.motivo;
} else {
  // Registrado pela rota (proposta ou contrato).
  let R = {};
  try { R = $('Rota - Gravar no sistema').first(0).json; } catch (e) { R = {}; }
  let P = {};
  try { P = $('Montar pedido da rota').first().json; } catch (e) { P = {}; }
  const ehContrato = P.tipo === 'contrato';
  const oQue = ehContrato ? 'Seu contrato' : 'Sua proposta';
  cliente = oQue + num + ' foi registrad' + (ehContrato ? 'o' : 'a') + ' no sistema.' + (A.precisaComplementar ? ' Só pra completar, quando puder nos passe: ' + A.camposFaltando.join(', ') + '.' : '');
  let resumo = (A.itens || []).length + ' itens lidos · ' + (R.itens ?? 0) + ' gravados';
  if (P.itensDescartados) resumo += ' · itens NÃO gravados: leitura não confiável';
  for (const a of R.avisos || []) resumo += ' · ' + a;
  const COMO = { codigo: 'pelo código', nome: 'pelo nome', cliente: 'pelo cliente' };
  if (R.obraIdentificadaComo) resumo += ' · obra identificada ' + (COMO[R.obraIdentificadaComo] || R.obraIdentificadaComo) + ' no documento';
  if (!ehContrato && R.contratoAditivoId) resumo += ' · aditivo do contrato ' + (A.contratoAditivo || '');
  if (ehContrato) resumo += R.propostaOrigemId ? ' · ligado à proposta ' + (A.proposta_referenciada || '') : (A.proposta_referenciada ? '' : ' · sem proposta citada');
  // A rota anexa o PDF ela mesma (01/10) e diz como foi.
  const anexoFalhou = R.anexoErro || null;
  resumo += anexoFalhou ? ' · ATENÇÃO: PDF NÃO anexado (' + String(anexoFalhou).slice(0, 120) + ')' : ' · PDF anexado';
  admin = (ehContrato ? '[CONTRATO REGISTRADO]' : '[PROPOSTA REGISTRADA]') + num + ' · ' + brl(A.valorProposta) + ' · cliente: ' + (A.cliente_nome || '—') + '\n' + resumo + '\nDocumento ' + docId;
}

if (A.extrator === 'groq') admin += '\n[extraído pela Groq; Gemini indisponível: ' + String(A.motivoGemini || 'falhou').slice(0, 160) + ']';

const contexto = { documentoId: docId, empresaId: ent.empresa_id, origem: 'processar-documento' };
return [
  { json: { destino: 'CLIENTE', canal: ent.canal, chat_id: ent.chat_id, texto: cliente, reply_to: ent.mensagem_id ?? null, opcoes: null, contexto } },
  { json: { destino: 'ADMIN', canal: 'TELEGRAM', chat_id: null, texto: admin, opcoes: null, contexto } },
];

// Adaptador: a regra mora em POST /api/ingestao/triagem-telegram (src/lib/bot-acesso.ts).
const u = $('Telegram Trigger').first().json ?? {};
const m = u.message ?? {};
const r = $('Rota - Triagem do Telegram').first().json ?? {};
if (r.ok === true) return (r.itens ?? []).map((json) => ({ json }));
// Rota fora do ar ou erro.
const privado = m.chat?.type === 'private';
const temDoc = !!m.document;
const erro = String(r.error ?? r.message ?? JSON.stringify(r)).slice(0, 300);
const ctx = { documentoId: null, empresaId: null, origem: 'telegram-entrada' };
const saida = [];
if (privado) saida.push({ json: { acao: 'responder', destino: 'CLIENTE', canal: 'TELEGRAM', chat_id: String(m.chat.id), reply_to: null, texto: 'Tivemos um problema ao receber sua mensagem. Tente de novo em alguns minutos.', opcoes: null, contexto: ctx } });
if (privado || temDoc) saida.push({ json: { acao: 'responder', destino: 'ADMIN', canal: 'TELEGRAM', chat_id: null, reply_to: null, texto: '[ERRO NA TRIAGEM] chat ' + (m.chat?.id ?? '?') + '\nErro: ' + erro, opcoes: null, contexto: ctx } });
return saida;

// Falha antes de o documento existir no banco: baixar do Telegram, guardar no
// storage ou assinar a URL.
const etapa = $prevNode.name;
const j = $input.first().json ?? {};
const bruto = JSON.stringify(j);
// Reentrega do mesmo update pelo Telegram: o arquivo ja esta no storage (409).
// Ja foi processado na primeira vez; descartar em silencio.
if (etapa === 'Supabase - Guardar PDF' && /409|Duplicate|already exists/i.test(bruto)) return [];
const t = $('Triar mensagem').first().json;
const erro = [j.error?.message, j.error?.description].filter(Boolean).join(' — ') || bruto.slice(0, 300);
const ctx = { documentoId: null, empresaId: t.empresa_id, origem: 'telegram-entrada' };
return [
  { json: { destino: 'CLIENTE', canal: 'TELEGRAM', chat_id: t.chat_id, reply_to: t.mensagem_id ?? null, texto: 'Tivemos um problema ao receber seu arquivo. Nossa equipe já foi avisada e vai te retornar em breve.', opcoes: null, contexto: ctx } },
  { json: { destino: 'ADMIN', canal: 'TELEGRAM', chat_id: null, texto: '[ERRO NA RECEPÇÃO] ' + t.nome_arquivo + ' (chat ' + t.chat_id + ', remetente ' + t.remetente_id + ')\nEtapa: ' + etapa + '\nErro: ' + erro, opcoes: null, contexto: ctx } },
];

// Reserva (decisao 20): o Gemini falhou (cota, 503, erro). A Groq nao le PDF,
// so texto: o PDF volta a ser arquivo para o 'Extrair texto do PDF'.
const j = $input.first().json ?? {};
const motivoGemini = [j.error?.message, j.error?.description].filter(Boolean).join(' — ') || 'falha sem mensagem';
const b64 = $('PDF para base64').first().json.pdfBase64;
const binario = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), 'documento.pdf', 'application/pdf');
return [{ json: { motivoGemini }, binary: { data: binario } }];

// A Groq so extrai de PDF com texto (gerado por sistema). PDF escaneado ou
// foto em PDF nao tem texto: sem o Gemini, nao ha como ler.
const texto = String($input.first().json.text ?? '').trim();
if (texto.replace(/\s+/g, '').length < 40) {
  throw new Error('PDF sem texto legivel (provavelmente escaneado ou foto). Com o Gemini indisponivel, a reserva so le PDF com texto. Envie o PDF original gerado pelo sistema.');
}
return [{ json: { texto, prompt: $('PDF para base64').first().json.prompt + '\n\nResponda SOMENTE com o objeto JSON, sem texto antes ou depois e sem bloco de codigo.' } }];

// Devolve a resposta da Groq no mesmo formato do Gemini, para o 'Analisar e
// decidir' nao saber de onde veio. Sem modo JSON estrito: com o documento de
// 16 itens a Groq recusava ('Failed to generate JSON'); o JSON e recortado aqui.
let c = String($input.first().json.choices?.[0]?.message?.content ?? '');
c = c.replace(/<think>[\s\S]*?<\/think>/g, '');
const a = c.indexOf('{');
const b = c.lastIndexOf('}');
if (a < 0 || b <= a) throw new Error('Groq nao devolveu JSON: ' + c.slice(0, 200));
const texto = c.slice(a, b + 1);
JSON.parse(texto);
return [{ json: {
  candidates: [{ content: { parts: [{ text: texto }] } }],
  extrator: 'groq',
  motivoGemini: $('Reserva - PDF de volta').first().json.motivoGemini,
} }];

// Envio dentro deste workflow (antes era o sub-workflow Notificar): 1 execucao
// por documento em vez de 2. O Notificar ficou so com o alerta de erro de sistema.
// chat_id do grupo de admin (decisao 5). ATENCAO: o mesmo numero esta no no
// 'Resolver destino' do Notificar — mudou o grupo, mude nos dois.
const ADMIN_CHAT_ID = '-5521155438';
const saida = [];
for (const item of $input.all()) {
  const e = item.json ?? {};
  const destino = String(e.destino ?? '').toUpperCase();
  const texto = typeof e.texto === 'string' ? e.texto.trim() : '';
  const chat_id = destino === 'ADMIN' ? ADMIN_CHAT_ID : (e.chat_id != null && String(e.chat_id).trim() !== '' ? String(e.chat_id).trim() : null);
  if (!texto || !chat_id || (destino !== 'ADMIN' && destino !== 'CLIENTE')) continue;
  saida.push({ json: { destino, chat_id, texto, reply_to: destino === 'CLIENTE' ? (Number(e.reply_to) || null) : null, contexto: e.contexto ?? null } });
}
return saida;

// Decisao 26: a gravacao e do gc-sistema, pelas rotas POST /api/ingestao/
// proposta e /contrato (a regra de src/lib/ingestao.ts, com teste). Aqui so se
// monta o corpo. Leitura nao confiavel: a proposta/contrato entra sem itens.
const BASE = 'https://gc-sistema-nine.vercel.app';
const A = $input.first().json;
const ent = $('Normalizar entrada').first().json;
const reg = $('Supabase - Criar registro').first(0).json;
const contrato = A.desfecho === 'CONTRATO';
const itensOk = A.itensConfiaveis !== false;
const corpo = {
  documentoId: reg.id,
  empresaId: ent.empresa_id,
  obraId: A.obraId || null,
  // Decisao 27: sem obraId, a rota identifica a obra por estas pistas.
  obra: { codigo: A.obraCodigo, nome: A.obraNome, cliente: A.cliente_nome },
  numero: A.numero,
  valorTotal: A.valorProposta,
  condicoesPagamento: A.condicoes_pagamento,
  observacao: 'Cliente: ' + (A.cliente_nome || '—') + (A.condicao_entrega ? ' | Entrega: ' + A.condicao_entrega : ''),
  itens: itensOk ? A.itens : [],
  origem: { canal: ent.canal === 'SISTEMA' ? 'tela' : ent.canal, chatId: ent.chat_id },
};
if (contrato) corpo.propostaReferenciada = A.proposta_referenciada || null;
else corpo.contratoAditivo = A.contratoAditivo || null;
return [{ json: { url: BASE + '/api/ingestao/' + (contrato ? 'contrato' : 'proposta'), corpo, tipo: contrato ? 'contrato' : 'proposta', itensDescartados: itensOk ? 0 : (A.itens || []).length } }];

// Decisão 31: o que a rota resposta-obra decidiu vira mensagem ao contato e,
// se a obra foi escolhida, a entrada que volta ao 'Normalizar entrada' (relê o
// PDF com a obra fixada). Erro da rota (inclusive 404 antes do deploy) cai no
// aviso de sempre.
const t = $('Triar mensagem').first().json;
const r = $input.first().json ?? {};
const ctx = { documentoId: r.documentoId ?? null, empresaId: t.empresa_id, origem: 'telegram-resposta-obra' };
const msg = (texto) => ({ json: { destino: 'CLIENTE', canal: 'TELEGRAM', chat_id: t.chat_id, reply_to: t.mensagem_id ?? null, texto, opcoes: null, contexto: ctx } });
const aoAdmin = (texto) => ({ json: { destino: 'ADMIN', canal: 'TELEGRAM', chat_id: null, texto, opcoes: null, contexto: ctx } });
if (r.acao === 'reprocessar' && r.entrada) {
  return [
    msg('Certo: obra ' + r.obra + '. Vamos registrar o documento e te avisamos aqui.'),
    { json: { ...r.entrada, reprocessar: true } },
  ];
}
if (r.acao === 'repetir' && r.pergunta) return [msg('Não entendi a resposta. ' + r.pergunta)];
if (r.acao === 'nenhuma') {
  return [
    msg('Certo. A equipe vai cadastrar a obra e registrar o documento. Obrigado!'),
    aoAdmin('[REVISÃO] Documento ' + r.documentoId + '\nQuem enviou disse que a obra não está cadastrada. Cadastre a obra e reprocesse em /documentos.'),
  ];
}
const noGrupo = String(t.chat_id).startsWith('-');
return [msg(noGrupo ? 'Para registrar uma proposta ou um contrato aqui no grupo, mande o PDF com /enviar na legenda.' : 'Para registrar uma proposta ou um contrato, envie o arquivo PDF aqui nesta conversa.')];
